components.css:
.ds-header-play-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 9999px;
  background: transparent;
  border: 1.5px solid #e5a21e;
  color: #e5a21e;
  cursor: pointer;
  transition: all 250ms cubic-bezier(0.16, 1, 0.3, 1);
  padding: 0;
}
.ds-header-play-btn:hover {
  transform: scale(1.08);
  background: rgba(229, 162, 30, 0.12);
  box-shadow: 0 0 8px rgba(229, 162, 30, 0.3);
}
.ds-header-play-btn.playing {
  background: #e5a21e;
  color: #0d0b17;
  box-shadow: 0 0 12px rgba(229, 162, 30, 0.4);
}
